#include <algorithm>
#include <iostream>
#include <string>

std::string reverse_str(const std::string& s) {
    std::string r(s);
    std::reverse(r.begin(), r.end());
    return r;
}

int main() {
    std::string s;
    std::getline(std::cin, s);
    std::cout << reverse_str(s) << "\n";
    return 0;
}

#include <iostream>
#include <stack>
#include <string>

bool isValid(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else {
            if (st.empty()) return false;
            char t = st.top(); st.pop();
            if ((c == ')' && t != '(') || (c == ']' && t != '[') ||
                (c == '}' && t != '{')) return false;
        }
    }
    return st.empty();
}

int main() {
    std::string s;
    std::getline(std::cin, s);
    std::cout << (isValid(s) ? "true" : "false") << "\n";
    return 0;
}
